"use strict";(()=>{var r=[];orcaViewer.register({async open(e){let t=e.size?await orcaViewer.readBytes(0,Math.min(e.size,64)):new Uint8Array;return r=[e.name,`${e.size} bytes`,[...t].map(i=>i.toString(16).padStart(2,"0")).join(" ")],{kind:"text",lineCount:r.length}},render(e){if(e.kind!=="text")throw new Error("Unsupported viewport");return{kind:"text",startLine:e.startLine,lines:r.slice(e.startLine,e.startLine+e.lineCount)}}});})();
